"""configloader — implement parse_config and get per README.md."""

import re

_INT_RE = re.compile(r"[+-]?\d+\Z")
_FLOAT_RE = re.compile(r"[+-]?(?:\d+\.\d*|\.\d+|\d+)(?:[eE][+-]?\d+)?\Z")


def _coerce(raw):
    """Turn a raw value string into a bool, int, float, or str."""
    if len(raw) >= 2 and raw.startswith('"') and raw.endswith('"'):
        return raw[1:-1]
    lowered = raw.lower()
    if lowered == "true":
        return True
    if lowered == "false":
        return False
    if _INT_RE.match(raw):
        return int(raw)
    if _FLOAT_RE.match(raw):
        return float(raw)
    return raw


def parse_config(text):
    config = {"": {}}
    section = ""
    for line in text.splitlines():
        line = line.strip()
        if not line or line[0] in "#;":
            continue
        if line.startswith("[") and line.endswith("]"):
            section = line[1:-1].strip()
            config.setdefault(section, {})
            continue
        key, sep, value = line.partition("=")
        if not sep:
            continue
        config[section][key.strip()] = _coerce(value.strip())
    return config


def get(config, dotted, default=None):
    section, sep, key = dotted.partition(".")
    if not sep:
        section, key = "", section
    return config.get(section, {}).get(key, default)

